import {ITEMS} from './core.js';
import {hudArt,missionObjectiveArt} from './hud-art.js';
import {approvedInterfaceGlyph} from './approved-interface-icons.js';
import {glyph} from './ui-art.js';
const icon=id=>approvedInterfaceGlyph(id),svg=id=>glyph(id);
export const expeditionHudMarkup=()=>`<div class="hud">
<header class="top"><section class="vital panel" aria-label="Vida"><div class="health-art">${hudArt('heart')}</div><div class="vital-body"><div class="vital-line"><span>Vida</span><b data-hud-field="hpLabel"></b></div><div data-hud-field="hpMeter" class="meter health-meter" role="progressbar" aria-label="Vida"><i data-hud-field="hpBar"></i></div></div></section><section data-hud-field="breathHud" class="breath panel" aria-label="Fôlego"><div class="breath-art">${hudArt('breath')}</div><div class="meter-body"><div class="vital-line"><span>Fôlego</span><b data-hud-field="breathLabel"></b></div><div data-hud-field="breathMeter" class="meter" role="progressbar" aria-label="Fôlego"><i data-hud-field="breathBar"></i></div><span data-hud-field="breathHint" hidden></span></div></section></header>
<div class="location"><div class="place panel"><b data-hud-field="runPlace"></b><small data-hud-field="runDepth"></small></div><div class="tools"><button data-hud-field="pause" aria-label="Pausar e consultar cartas · ESC">Ⅱ<kbd>ESC</kbd></button><button data-hud-field="settings" aria-label="Menu principal" hidden>⋯</button></div></div>
<section class="combo" aria-label="Combo"><strong data-hud-field="combo"></strong><small>Combo</small></section>
<section data-hud-field="missionHud" class="mission panel"><div class="objective-art" data-hud-field="missionIcon"></div><div><span data-hud-field="missionTask"></span><strong data-hud-field="missionProgress"></strong><small data-hud-field="missionTime"></small></div><span data-hud-field="missionTier" hidden></span><span data-hud-field="missionName" hidden></span></section>
<section data-hud-field="runControls" class="rail panel" aria-label="Guia visual do ritmo"><div class="track"><div class="energy-fill"></div><i class="energy-edge"></i><div data-hud-field="perfectZone" class="perfect-zone"></div><div class="hit-line" aria-hidden="true"></div>${Array.from({length:5},()=>`<i class="hud-note" aria-hidden="true">${icon('ear')}</i>`).join('')}<i class="contact"></i><i class="contact-rays"></i></div><div class="rail-footer"><strong data-hud-field="trackName"></strong><span data-hud-field="timing">SIGA O PULSO</span><b data-hud-field="bpmLabel"></b><b data-hud-field="railMultiplier"></b></div></section>
<div data-hud-field="itemBar" class="items" aria-label="Consumíveis, teclas 1, 2, 3">${ITEMS.map(i=>`<button data-hud-field="item-${i.id}" class="item"><kbd>${i.key}</kbd>${hudArt(i.id)}<b class="quantity">0</b></button>`).join('')}</div>
<section class="score panel" aria-label="Pontuação deste andar"><div class="score-top"><span>Pontos</span><b data-hud-field="scoreValue"></b></div><div class="score-progress"><div data-hud-field="earnedStars" class="score-stars"></div><div class="meter" data-hud-field="scoreMeter" role="progressbar" aria-orientation="vertical" aria-label="Progresso das cinco estrelas"><i data-hud-field="scoreFill"></i></div><div data-hud-field="scoreMarks" class="score-marks"></div></div><small data-hud-field="scoreNext"></small></section>
<div class="cargo"><span data-hud-field="runBag"></span><button data-hud-field="extract" class="extract">${hudArt('home')}<span>Voltar</span><kbd>E</kbd></button></div>
<div hidden><span data-hud-field="bank"></span><span data-hud-field="walletStars"></span><span data-hud-field="record"></span><span data-hud-field="runGoal"></span><span data-hud-field="place"></span><div class="exploration"><b data-hud-field="explorationValue"></b><div data-hud-field="explorationMeter"><i data-hud-field="explorationBar"></i></div></div></div>
</div>`;
